"""Selmer fan: Gaussian binomial coefficients and their symmetries."""
from __future__ import annotations
from math import comb
from typing import List


def gauss_binom(q: int, n: int, k: int) -> int:
    """Number of k-dim subspaces of F_q^n via the forward q-Pascal recurrence."""
    if k < 0 or k > n:
        return 0
    row: List[int] = [1] + [0] * n
    for m in range(1, n + 1):
        new = [1] + [0] * n
        for j in range(1, m + 1):
            new[j] = row[j - 1] + (q ** j) * row[j]
        row = new
    return row[k]


def fan(q: int, n: int) -> List[int]:
    return [gauss_binom(q, n, k) for k in range(n + 1)]


if __name__ == "__main__":
    for q, n in [(2, 4), (3, 3), (5, 4)]:
        f = fan(q, n)
        print(f"q={q}, n={n}: {f}  self-dual={all(f[k]==f[n-k] for k in range(n+1))}")
    print("q=1 recovers Pascal:", fan(1, 5), [comb(5, k) for k in range(6)])

"""Parity rigidity of +/-1 rank walks."""
from __future__ import annotations
from itertools import product
from typing import List


def build_walk(start: int, steps: List[int]) -> List[int]:
    w = [start]
    for s in steps:
        w.append(w[-1] + s)
    return w


def parity_oracle(start: int, n: int) -> int:
    return (start + n) % 2


def verify(start: int, n: int) -> bool:
    return all(
        build_walk(start, list(s))[n] % 2 == parity_oracle(start, n)
        for s in product((1, -1), repeat=n)
    )


if __name__ == "__main__":
    for start, n in [(0, 4), (3, 7), (-2, 6)]:
        print(f"start={start}, n={n}: parity fixed for all walks? {verify(start, n)}"
              f"  predicted={parity_oracle(start, n)}")

"""Cross-check: dual q-Pascal recurrence vs forward definition."""
from __future__ import annotations
from typing import List


def gauss_binom(q: int, n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    row: List[int] = [1] + [0] * n
    for m in range(1, n + 1):
        new = [1] + [0] * n
        for j in range(1, m + 1):
            new[j] = row[j - 1] + (q ** j) * row[j]
        row = new
    return row[k]


def dual_rhs(q: int, n: int, k: int) -> int:
    return (q ** (n - k)) * gauss_binom(q, n, k) + gauss_binom(q, n, k + 1)


if __name__ == "__main__":
    ok = all(
        gauss_binom(q, n + 1, k + 1) == dual_rhs(q, n, k)
        for q in range(2, 6) for n in range(7) for k in range(7)
    )
    print("dual recurrence matches forward definition (q<=5, n,k<=6):", ok)

